/**
 * 03-cc-merchant-directory.js
 *
 * Loads an auto-learned merchant→ledger directory into cc_merchant_directory
 * for ONE brand. Generated by reco-engine/tools/build_cc_seed.py from that
 * brand's already-booked credit-card working files.
 *
 * Idempotent: ON CONFLICT (brand_id, key_type, key_value) refreshes the ledger,
 * so re-running after regenerating the JSON updates rather than duplicates.
 *
 * Every entry is validated against the brand's ledger_master first — seeding a
 * ledger that no longer exists in the chart of accounts would produce bookings
 * Tally cannot import. Unknown ledgers are reported and skipped, never inserted.
 *
 * Touches nothing belonging to other agents: cc_merchant_directory is this
 * agent's own table, and bank_payee_directory / bank_side_rules are not read
 * or written here.
 *
 * Usage:
 *   node seeders/03-cc-merchant-directory.js --brand "Koparo" \
 *        --file ../db-restructure/024-koparo-cc-directory.json [--dry-run]
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { Sequelize } = require('sequelize');
require('dotenv').config({ path: path.join(__dirname, '..', '.env') });

function arg(name, fallback = null) {
  const i = process.argv.indexOf(`--${name}`);
  return i > -1 && process.argv[i + 1] ? process.argv[i + 1] : fallback;
}
const DRY = process.argv.includes('--dry-run');

async function main() {
  const brandName = arg('brand');
  const file = arg('file');
  if (!brandName || !file) {
    console.error('Usage: --brand "<name>" --file <seed.json> [--dry-run]');
    process.exit(1);
  }

  const seedPath = path.isAbsolute(file) ? file : path.join(__dirname, '..', file);
  const seed = JSON.parse(fs.readFileSync(seedPath, 'utf8'));

  // Mirror src/config/database.js: in unified mode the DB is UNIFIED_DB_NAME,
  // NOT DB_NAME (which still points at the legacy colonel-master and holds the
  // OLD sequential brand ids — connecting there resolved Koparo to a stale
  // b0000000-… id with no ledger_master at all).
  const UNIFIED = process.env.USE_UNIFIED_DB !== 'false';
  const dbName = UNIFIED
    ? (process.env.UNIFIED_DB_NAME || 'colonel_agent_accountant')
    : (process.env.DB_NAME_MASTER || process.env.DB_NAME);

  const sequelize = new Sequelize(
    dbName,
    process.env.DB_USER || 'postgres',
    process.env.DB_PASSWORD,
    { host: process.env.DB_HOST || 'localhost', port: process.env.DB_PORT || 5432,
      dialect: 'postgres', logging: false },
  );

  const [[brand]] = await sequelize.query(
    'SELECT id, name FROM brands WHERE lower(name) = lower($1) LIMIT 1',
    { bind: [brandName] },
  );
  if (!brand) throw new Error(`Brand not found: ${brandName}`);
  console.log(`DB: ${dbName}`);
  console.log(`Brand: ${brand.name}  (${brand.id})`);

  const [coaRows] = await sequelize.query(
    'SELECT ledger_name FROM ledger_master WHERE brand_id = $1',
    { bind: [brand.id] },
  );
  const coa = new Map(coaRows.map((r) => [String(r.ledger_name).trim().toLowerCase(),
    String(r.ledger_name).trim()]));
  console.log(`Chart of accounts: ${coa.size} ledgers`);

  const valid = [];
  const missing = new Map();
  for (const row of seed) {
    const key = String(row.ledger || '').trim().toLowerCase();
    const real = coa.get(key);
    if (!real) {
      missing.set(row.ledger, (missing.get(row.ledger) || 0) + 1);
      continue;
    }
    // Store the COA's exact spelling, not the working file's — the working files
    // drift ("Bank Charges" vs the real "Bank charges") and only the COA spelling
    // imports into Tally cleanly.
    valid.push({ key_type: row.key_type, key_value: row.key_value, ledger: real });
  }

  console.log(`Seed entries: ${seed.length}  valid: ${valid.length}  skipped: ${seed.length - valid.length}`);
  if (missing.size) {
    console.log('\nSkipped — ledger not in this brand\'s chart of accounts:');
    for (const [led, n] of [...missing].sort((a, b) => b[1] - a[1])) {
      console.log(`   ${String(n).padStart(3)}x  ${led}`);
    }
  }
  if (DRY) { console.log('\n--dry-run: nothing written.'); await sequelize.close(); return; }

  let written = 0;
  const t = await sequelize.transaction();
  try {
    // RLS is FORCED on this table, so the brand GUC must be set for the session
    // even as a superuser-owned connection; the default on brand_id reads it too.
    await sequelize.query(`SET LOCAL app.brand_id = '${brand.id}'`, { transaction: t });
    for (const row of valid) {
      await sequelize.query(
        `INSERT INTO cc_merchant_directory (brand_id, key_type, key_value, ledger, source)
         VALUES ($1, $2, $3, $4, 'seed')
         ON CONFLICT (brand_id, key_type, key_value)
         DO UPDATE SET ledger = EXCLUDED.ledger, updated_at = NOW()`,
        { bind: [brand.id, row.key_type, row.key_value, row.ledger], transaction: t },
      );
      written += 1;
    }
    await t.commit();
  } catch (e) {
    await t.rollback();
    throw e;
  }

  const [[{ n }]] = await sequelize.query(
    'SELECT count(*)::int AS n FROM cc_merchant_directory WHERE brand_id = $1',
    { bind: [brand.id] },
  );
  console.log(`\nUpserted ${written} rows. cc_merchant_directory now holds ${n} for ${brand.name}.`);
  await sequelize.close();
}

main().catch((e) => { console.error('SEED FAILED:', e.message); process.exit(1); });
